// mixedAssertRenderZeroOnError asserts Render returns zero alongside any error.
func mixedAssertRenderZeroOnError(
	tb testing.TB,
	m Mixed,
	fx MixedFixture,
) {
	tb.Helper()
	ctx, cancel := context.WithCancel(tb.Context())
	cancel()
	got, err := m.Render(ctx, fx.In())
	if err == nil {
		tb.Skip("Render answered for a cancelled context, so this check has no error to inspect")
	}

	var zero string
	if got != zero {
		tb.Errorf("Render must return the zero value alongside an error: got %+v, want %+v (err %v)",
			got, zero, err)
	}
}

